CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,uuid TEXT UNIQUE NOT NULL,limit_gb REAL DEFAULT 0,used_gb REAL DEFAULT 0,expiry_days INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,is_active INTEGER DEFAULT 1,limit_req INTEGER DEFAULT 0,used_req INTEGER DEFAULT 0,port INTEGER DEFAULT 443,tls INTEGER DEFAULT 1,ip_limit INTEGER DEFAULT 0,block_porn INTEGER DEFAULT 0,block_ads INTEGER DEFAULT 0,ips TEXT DEFAULT '',fingerprint TEXT DEFAULT 'chrome',remark TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_users_uuid ON users(uuid);
